export function parseDataUrl(
  data: string,
  fallbackMime: string,
): { data: string; mimeType: string } {
  if (typeof data === "string" && data.includes(";base64,")) {
    const segments = data.split(";base64,");
    return {
      data: segments[1],
      mimeType: segments[0].replace("data:", ""),
    };
  }
  return { data, mimeType: fallbackMime };
}

